import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def issq(v):
    r = 0
    while r * r < v:
        r += 1
    return r * r == v
best = 0
cur = 0
for x in a:
    if issq(x):
        cur += 1
        if cur > best:
            best = cur
    else:
        cur = 0
print(best)

